// Crate Pusher: push every crate onto a target. You can push but never pull, so a crate in
// a corner is stuck. Levels are generated by playing backwards: crates start on their
// targets and the warehouse keeper pulls them away, so every level has a solution.

import { CanvasGame } from '../kit/canvasGame.js';
import { tool } from '../kit/toolbar.js';
import { fillRound, text, colors } from '../core/canvas.js';

const W = 560, H = 560;
const DIRS = { up: [0, -1], down: [0, 1], left: [-1, 0], right: [1, 0] };
const LEVELS = 12;

/** Builds a solvable level: { w, h, walls, goals, crates, player } with cell indices. */
export function generate(level) {
	const k = level < 2 ? 2 : level < 6 ? 3 : 4;
	const iw = level < 4 ? 6 : 7, ih = level < 4 ? 6 : 7;
	const w = iw + 2, h = ih + 2;
	let best = null;
	for (let attempt = 0; attempt < 60; attempt++) {
		const walls = new Uint8Array(w * h);
		for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (x === 0 || y === 0 || x === w - 1 || y === h - 1 || Math.random() < 0.13) walls[y * w + x] = 1;
		const floor = [];
		for (let i = 0; i < w * h; i++) if (!walls[i]) floor.push(i);
		if (!connected(walls, w, h, floor)) continue;
		const pickFrom = floor.slice().sort(() => Math.random() - 0.5);
		const goals = pickFrom.slice(0, k);
		const crates = new Set(goals);
		let player = pickFrom[k];
		const moved = new Set();
		for (let step = 0; step < 220; step++) {
			const reach = region(walls, w, h, crates, player);
			const pulls = [];
			for (const p of reach) for (const d of [1, -1, w, -w]) {
				if (crates.has(p + d) && !walls[p - d] && !crates.has(p - d)) pulls.push([p, d]);
			}
			if (!pulls.length) break;
			const [p, d] = pulls[Math.floor(Math.random() * pulls.length)];
			crates.delete(p + d);
			crates.add(p);
			moved.add(p + d);
			player = p - d;
		}
		const list = [...crates];
		const off = list.filter((c) => !goals.includes(c)).length;
		if (off < k) continue;
		const spread = list.reduce((s, c) => s + Math.min(...goals.map((g) => Math.abs((g % w) - (c % w)) + Math.abs(Math.floor(g / w) - Math.floor(c / w)))), 0);
		if (!best || spread > best.spread) best = { w, h, walls, goals, crates: list, player, spread };
		if (spread >= k * 3) break;
	}
	return best ?? generate(level);
}

function connected(walls, w, h, floor) {
	const seen = new Set([floor[0]]);
	const queue = [floor[0]];
	while (queue.length) {
		const c = queue.pop();
		for (const d of [1, -1, w, -w]) if (!walls[c + d] && !seen.has(c + d)) { seen.add(c + d); queue.push(c + d); }
	}
	return seen.size === floor.length;
}

function region(walls, w, h, crates, from) {
	const seen = new Set([from]);
	const queue = [from];
	while (queue.length) {
		const c = queue.pop();
		for (const d of [1, -1, w, -w]) {
			const n = c + d;
			if (!walls[n] && !crates.has(n) && !seen.has(n)) { seen.add(n); queue.push(n); }
		}
	}
	return seen;
}

export default class CratePusher extends CanvasGame {
	static W = W;
	static H = H;

	buildToolbar() {
		this.label = tool.label('');
		return tool.bar(this.label, tool.button('Undo', () => this.undo()), tool.button('Restart level', () => this.load(this.data)), tool.button('New layout', () => this.startLevel(this.level), { title: 'Generate another warehouse for this level' }));
	}

	reset() {
		super.reset();
		this.score = 0;
		this.ctx.score(0);
		this.startLevel(0);
	}

	restore(data) {
		this.score = data.score ?? 0;
		this.ctx.score(this.score);
		this.level = data.level ?? 0;
		this.load(data.map);
	}

	startLevel(level) {
		this.level = level;
		const m = generate(level);
		this.load({ w: m.w, h: m.h, walls: [...m.walls], goals: m.goals, crates: m.crates, player: m.player });
	}

	load(data) {
		this.data = data;
		this.w = data.w;
		this.h = data.h;
		this.walls = data.walls;
		this.goals = new Set(data.goals);
		this.crates = new Set(data.crates);
		this.player = data.player;
		this.history = [];
		this.moves = 0;
		this.pushes = 0;
		this.face = [0, 1];
		this.won = false;
		this.slide = null;
		this.label.textContent = `Level ${this.level + 1} / ${LEVELS}`;
		this.ctx.info('Arrows / WASD or swipe to move');
		this.ctx.saveProgress({ level: this.level, score: this.score, map: data });
		this.wake();
	}

	move(dir) {
		if (!this.running || this.won) return;
		const [dx, dy] = DIRS[dir];
		const d = dx + dy * this.w;
		const to = this.player + d;
		this.face = [dx, dy];
		if (this.walls[to]) return this.ctx.audio.play('thud');
		if (this.crates.has(to)) {
			const beyond = to + d;
			if (this.walls[beyond] || this.crates.has(beyond)) return this.ctx.audio.play('thud');
			this.history.push({ player: this.player, crates: [...this.crates] });
			this.crates.delete(to);
			this.crates.add(beyond);
			this.pushes++;
			this.ctx.audio.play(this.goals.has(beyond) ? 'chip' : 'move');
			if (this.goals.has(beyond)) this.burst(...this.center(beyond), { count: 14, color: '#fde047', speed: 120, life: 0.5, shape: 'star', size: 3 });
		} else {
			this.history.push({ player: this.player, crates: [...this.crates] });
			this.ctx.audio.play('tick');
		}
		this.slide = { from: this.player, t: 0 };
		this.player = to;
		this.moves++;
		this.ctx.info(`Moves ${this.moves} · Pushes ${this.pushes}`);
		if ([...this.crates].every((c) => this.goals.has(c))) this.win();
		this.wake();
	}

	undo() {
		if (!this.running || this.won || !this.history.length) return;
		const s = this.history.pop();
		this.player = s.player;
		this.crates = new Set(s.crates);
		this.moves++;
		this.ctx.audio.play('swoosh');
		this.wake();
	}

	win() {
		this.won = true;
		const gain = 100 + this.crates.size * 50 + Math.max(0, 150 - this.moves);
		this.score += gain;
		this.ctx.score(this.score);
		this.ctx.audio.play('levelup');
		this.ctx.fx.confetti({ count: 50 });
		setTimeout(() => {
			if (!this.running) return;
			if (this.level + 1 >= LEVELS) return this.finish({ win: true, title: 'Warehouse sorted!', message: `All ${LEVELS} warehouses done.`, score: this.score });
			this.startLevel(this.level + 1);
			this.ctx.fx.banner(`Level ${this.level + 1}`);
		}, 1000);
	}

	key(action) { if (DIRS[action]) this.move(action); else if (action === 'action') this.undo(); }

	pointerDown(p) { this.swipe = { x: p.x, y: p.y }; }
	pointerUp(p) {
		if (!this.swipe) return;
		const dx = p.x - this.swipe.x, dy = p.y - this.swipe.y;
		this.swipe = null;
		if (Math.hypot(dx, dy) < 12) {
			// a tap: step toward the tapped side of the keeper
			const [px, py] = this.center(this.player);
			const tx = p.x - px, ty = p.y - py;
			if (Math.hypot(tx, ty) < this.cell() * 0.4) return;
			return this.move(Math.abs(tx) > Math.abs(ty) ? (tx > 0 ? 'right' : 'left') : (ty > 0 ? 'down' : 'up'));
		}
		this.move(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up'));
	}

	cell() { return Math.floor(Math.min(W / this.w, H / this.h)); }
	center(i) {
		const s = this.cell(), x0 = (W - s * this.w) / 2, y0 = (H - s * this.h) / 2;
		return [x0 + (i % this.w + 0.5) * s, y0 + (Math.floor(i / this.w) + 0.5) * s];
	}

	busy() { return Boolean(this.slide); }
	tick(dt) { if (this.slide && (this.slide.t += dt / 0.09) >= 1) this.slide = null; }

	draw(g) {
		g.fillStyle = '#1f2937';
		g.fillRect(0, 0, W, H);
		const s = this.cell();
		for (let i = 0; i < this.w * this.h; i++) {
			const [cx, cy] = this.center(i);
			const x = cx - s / 2, y = cy - s / 2;
			if (this.walls[i]) {
				// draw only walls that touch the floor, so the room has a clean outline
				const nearFloor = [1, -1, this.w, -this.w, this.w + 1, this.w - 1, -this.w + 1, -this.w - 1].some((d) => this.walls[i + d] === 0);
				if (nearFloor) { fillRound(g, x + 1, y + 1, s - 2, s - 2, 4, '#57534e'); fillRound(g, x + 4, y + 4, s - 8, s * 0.3, 3, '#78716c'); }
				continue;
			}
			fillRound(g, x + 1, y + 1, s - 2, s - 2, 3, '#d6d3d1');
			if (this.goals.has(i)) { g.strokeStyle = '#dc2626'; g.lineWidth = 3; g.beginPath(); g.arc(cx, cy, s * 0.22, 0, Math.PI * 2); g.stroke(); }
		}
		for (const c of this.crates) {
			const [cx, cy] = this.center(c);
			const on = this.goals.has(c);
			fillRound(g, cx - s * 0.42, cy - s * 0.42, s * 0.84, s * 0.84, 6, on ? '#16a34a' : '#b45309');
			g.strokeStyle = on ? '#bbf7d0' : '#fcd34d';
			g.lineWidth = 3;
			g.strokeRect(cx - s * 0.3, cy - s * 0.3, s * 0.6, s * 0.6);
			g.beginPath(); g.moveTo(cx - s * 0.3, cy - s * 0.3); g.lineTo(cx + s * 0.3, cy + s * 0.3); g.stroke();
		}
		let [px, py] = this.center(this.player);
		if (this.slide) {
			const [fx, fy] = this.center(this.slide.from);
			px = fx + (px - fx) * this.slide.t;
			py = fy + (py - fy) * this.slide.t;
		}
		g.fillStyle = colors.accent;
		g.beginPath(); g.arc(px, py, s * 0.34, 0, Math.PI * 2); g.fill();
		g.fillStyle = '#fff';
		const [fx, fy] = this.face;
		for (const side of [-1, 1]) { g.beginPath(); g.arc(px + fx * s * 0.12 + (fy ? side * s * 0.12 : 0), py + fy * s * 0.12 + (fx ? side * s * 0.12 : 0) - (fy ? 0 : s * 0.04), s * 0.07, 0, Math.PI * 2); g.fill(); }
		const done = [...this.crates].filter((c) => this.goals.has(c)).length;
		text(g, `${done} / ${this.crates.size}`, W - 12, 16, { size: 14, align: 'right', color: '#e5e7eb' });
	}
}
